<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsToMany;class Media extends Model{protected $table='media';protected $fillable=['name','file','external_url','provider','media_type','mime','size','alt','collection'];public function getEmbedUrlAttribute():?string{if(!$this->external_url)return null;$u=$this->external_url;if($this->provider==='youtube'){if(preg_match('~(?:youtu\\.be/|youtube\\.com/(?:watch\\?v=|shorts/|embed/))([A-Za-z0-9_-]{6,})~',$u,$m))return 'https://www.youtube-nocookie.com/embed/'.$m[1];}if($this->provider==='rutube'){if(preg_match('~rutube\\.ru/(?:video|shorts)/([a-zA-Z0-9]+)~',$u,$m))return 'https://rutube.ru/play/embed/'.$m[1];}return null;}public function news():BelongsToMany{return $this->belongsToMany(News::class,'news_media')->withPivot('sort');}public function galleries():BelongsToMany{return $this->belongsToMany(Gallery::class,'gallery_media')->withPivot('sort');}}